import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {import('three/webgpu').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Texture } = ctx.THREE;

  // --- Geometry (preserve image aspect) ---
  const sourceRect = (config.atlas && config.atlas.sourceRect) || { width: 1, height: 1 };
  const aspect = sourceRect.width / sourceRect.height;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // --- Material ---
  const material = new MeshBasicNodeMaterial({ transparent: true });

  // Load texture asynchronously, but creation stays synchronous.
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0);

  // --- Container Group ---
  const container = new Group();
  container.add(mesh);

  // --- Interaction Timelines ---
  const riseTimeline = gsap.timeline({ paused: true });
  riseTimeline.to(
    mesh.position,
    {
      y: 0.15,
      duration: 0.3,
      ease: 'power3.out',
    }
  );

  // --- Handlers ---
  const handlers = {
    hover: (enter) => {
      if (enter) {
        riseTimeline.play();
      } else {
        riseTimeline.reverse();
      }
    },
    click: () => {
      ctx.emit('hub-journal.select', {});
    },
  };
  container.userData.handlers = handlers;

  // --- Cinematic primitives (if any) ---
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const instance = ctx.primitives[primitive.name](
        container,
        primitive.params || {}
      );
      primitiveInstances.push(instance);
    }
  }

  // --- Cleanup ---
  container.userData.cleanup = () => {
    // dispose material & texture
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();
    geometry.dispose();

    // kill GSAP timeline
    riseTimeline.kill();

    // cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
  };

  return container;
}
